/**
 * get_schema_overview tool — high-level summary of the entire GraphQL schema.
 */
import { z } from 'zod';
export const getSchemaOverviewSchema = z.object({});
const SMALL_ENUM_THRESHOLD = 6;
export function handleGetSchemaOverview(schema) {
    if (!schema) {
        return 'Schema data not available. Data files may be missing — try reinstalling the package.';
    }
    const sections = [];
    // Root Queries
    const queryRows = schema.rootQueries.map(q => {
        const returns = q.isList ? `[${q.returnType}]` : q.returnType;
        const desc = q.description.length > 60 ? q.description.slice(0, 57) + '...' : q.description;
        return `| \`${q.name}\` | \`${returns}\` | ${desc} |`;
    });
    sections.push(`## Root Queries (${schema.rootQueries.length})\n\n| Query | Returns | Description |\n|-------|---------|-------------|\n${queryRows.join('\n')}`);
    // Object Types
    const objectLines = schema.objectTypes.map(t => {
        const impl = t.implements?.length ? ` [implements: ${t.implements.join(', ')}]` : '';
        return `- **${t.name}** (${t.fields.length} fields)${impl}`;
    });
    sections.push(`## Object Types (${schema.objectTypes.length})\n\n${objectLines.join('\n')}`);
    // Input Types
    const inputLines = schema.inputTypes.map(t => `- **${t.name}** (${t.fields.length} fields)`);
    sections.push(`## Input Types (${schema.inputTypes.length})\n\n${inputLines.join('\n')}`);
    // Enums
    const enumLines = schema.enums.map(e => {
        if (e.values.length <= SMALL_ENUM_THRESHOLD) {
            const vals = e.values.map(v => `\`${v.name}\``).join(', ');
            return `- **${e.name}**: ${vals}`;
        }
        return `- **${e.name}** (${e.values.length} values)`;
    });
    sections.push(`## Enums (${schema.enums.length})\n\n${enumLines.join('\n')}`);
    // Interfaces
    const ifaceLines = schema.interfaces.map(t => `- **${t.name}** (${t.fields.length} fields)`);
    sections.push(`## Interfaces (${schema.interfaces.length})\n\n${ifaceLines.join('\n')}`);
    // Scalars
    const scalarLines = schema.scalars.map(s => {
        const desc = s.description.length > 80 ? s.description.slice(0, 77) + '...' : s.description;
        return `- **${s.name}** — ${desc}`;
    });
    sections.push(`## Scalars (${schema.scalars.length})\n\n${scalarLines.join('\n')}`);
    const total = schema.rootQueries.length + schema.objectTypes.length + schema.inputTypes.length
        + schema.enums.length + schema.interfaces.length + schema.scalars.length;
    return `# OneSource GraphQL Schema Overview

${total} types total across ${schema.rootQueries.length} queries, ${schema.objectTypes.length} objects, ${schema.inputTypes.length} inputs, ${schema.enums.length} enums, ${schema.interfaces.length} interfaces, ${schema.scalars.length} scalars.

${sections.join('\n\n')}

---

Use \`get_type_definition\` for full field details on any type. Use \`get_query_reference\` for complete query signatures.`;
}
